return ['domain'=>'slider-block','plural-forms'=>NULL,'language'=>'pt_PT','project-id-version'=>'Slider Block 0.2.0','pot-creation-date'=>'2023-09-07T01:13:01+00:00','po-revision-date'=>'2023-09-07 02:49+0100','x-generator'=>'Poedit 3.3.2','messages'=>['Slider Block'=>'Bloco de Slider','Display a slider.'=>'Exibe um slider.','Previous slide'=>'Slide anterior','Next slide'=>'Slide seguinte','This is the first slide'=>'Este é o primeiro slide','This is the last slide'=>'Este é o último slide','Go to slide {{index}}'=>'Ir para o slide {{index}}','{{index}} / {{slidesLength}}'=>'{{index}} / {{slidesLength}}','Heading'=>'Título','Settings'=>'Configurações','URL Hash'=>'Hash de URL','A URL hash is used to link to a specific slide that allows you to load the page with that slide open.'=>'Um hash de URL é usado para ligar a um slide específico que permite carregar a página com esse slide aberto.','Add slide'=>'Adicionar slide','Loop'=>'Ciclo','When enabled, the slider will behave as a carousel.'=>'Quando activado, o slider comportar-se-á como um carrossel.','Rewind'=>'Rebobinar','When enabled, clicking the "next" navigation button on the last slide will take you back to the first slide. When you click the "previous" navigation button on the first slide, it will take you to the last slide.'=>'Quando activado, clicar no botão de navegação “seguinte” no último slide leva-o de volta ao primeiro slide. Se clicar no botão de navegação “anterior” no primeiro slide, regressará ao último slide.','Autoplay'=>'Reprodução automática','Free Mode'=>'Modo livre','Navigation'=>'Navegação','Pagination'=>'Paginação','Hash Navigation'=>'Navegação por Hash','When enabled, you can load a page with a specific slide open. Each slide requires a "URL Hash", which can be set on each slide block.'=>'Quando activado, pode carregar uma página com um slide específico aberto. Cada slide requer um "Hash de URL", que pode ser definido em cada bloco de slide.','Speed'=>'Velocidade','Duration of transition between slides (in milliseconds).'=>'Duração da transição entre slides (em milissegundos).','Width'=>'Largura','The slider will not be responsive if this parameter is set.'=>'O slider não será responsivo se este parâmetro estiver definido.','Height'=>'Altura','Auto Height'=>'Altura automática','When enabled, the slider will adjust its height to match the height of the currently active slide.'=>'Quando activada, o slider ajustará a sua altura para corresponder à altura do slide actualmente activo.','Per View'=>'Por visualização','Number of slides per view (slides visible at the same time).'=>'Número de slides por visualização (slides visíveis ao mesmo tempo).','Space Between Slides'=>'Espaço entre slides','The distance between slides.'=>'A distância entre os slides.','Centered Slides'=>'Slides centrados','When enabled, the active slide will be centered.'=>'Quando activado, o slide activo será centrado.','Delay'=>'Atraso','Delay between transitions (in milliseconds).'=>'Atraso entre transições (em milissegundos).','Pause on Hover'=>'Pausa ao passar o rato','When enabled autoplay will be paused on pointer (mouse) enter over the slider.'=>'Quando activada, a reprodução automática é interrompida quando o ponteiro (rato) passa sobre o slider.','Type'=>'Tipo','Bullets'=>'Indicadores','Fraction'=>'Fracção','Progress Bar'=>'Barra de progresso','Accessibility'=>'Acessibilidade','Aria Label'=>'Aria Label','Sets an aria-label attribute to the root element.'=>'Define um atributo aria-label para o elemento raiz.','block titleSlide'=>'Slide','block descriptionDisplay a slider.'=>'Exibe um slider.','block titleSlider'=>'Slider','block keywordslider'=>'slider','block keywordcarousel'=>'carrossel','Slider Block is no longer maintained. It is replaced by <a href="%1$s">Outstand Carousel</a>, which can run alongside it while you migrate. Follow the <a href="%2$s">migration guide</a> to convert your sliders in the editor or with WP-CLI.'=>'O Slider Block deixou de ser mantido. Foi s